121: int GetLotDecimals(const string sym)
122: {
123:    double step = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
124:    if(step <= 0.000001) return 2;
125:    if(step >= 1.0)      return 0;
126:    if(step >= 0.1)      return 1;
127:    if(step >= 0.01)     return 2;
128:    if(step >= 0.001)    return 3;
129:    return 4;
130: }
131: 
132: double NormalizeLot(double lot, const string sym)
133: {
134:    double stepLot = SymbolInfoDouble(sym, SYMBOL_VOLUME_STEP);
135:    double minLot  = SymbolInfoDouble(sym, SYMBOL_VOLUME_MIN);
136:    double maxLot  = SymbolInfoDouble(sym, SYMBOL_VOLUME_MAX);
137:    
138:    if(stepLot <= 0.0) stepLot = 0.01;
139:    if(minLot <= 0.0)  minLot = 0.01;
140:    if(maxLot <= 0.0)  maxLot = 100.0;
141:    
142:    // Arredondamento para baixo (MathFloor) baseado no SYMBOL_VOLUME_STEP p/ segurança absoluta
143:    double norm = MathFloor(lot / stepLot) * stepLot;
144:    if(norm < minLot) norm = minLot;
145:    if(norm > maxLot) norm = maxLot;
146:    
147:    int dec = GetLotDecimals(sym);
148:    return NormalizeDouble(norm, dec);
149: }
